'use strict';

class TokenBucket {
  constructor(opts) {
    if (opts === null || typeof opts !== 'object' || Array.isArray(opts)) {
      throw new RangeError('options object is required');
    }
    const capacity = opts.capacity;
    const refillPerSecond = opts.refillPerSecond;
    const now = opts.now;

    if (typeof capacity !== 'number' || !Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative number');
    }

    this._capacity = capacity;
    this._ratePerMs = refillPerSecond / 1000;
    if (typeof now === 'function') {
      this._nowFn = now;
    } else {
      this._nowFn = Date.now;
    }

    const t0 = this._clockNow();
    this._lastTime = Number.isFinite(t0) ? t0 : 0;
    this._tokens = capacity; // bucket starts full
  }

  _clockNow() {
    try {
      return this._nowFn();
    } catch (e) {
      if (!Number.isFinite(this._lastTime)) throw e;
      return this._lastTime;
    }
  }

  // Advance bucket to current time, applying refill. If clock went backwards
  // relative to the max seen time, do not add or remove tokens (keep last state).
  _advance() {
    const t = Number.isFinite(this._clockNow()) ? this._clockNow() : this._lastTime;
    if (t > this._lastTime) {
      const dtMs = t - this._lastTime; // >= 0
      this._tokens = Math.min(
        this._capacity,
        this._tokens + this._ratePerMs * dtMs
      );
      this._lastTime = t;
    } else if (t < this._lastTime) {
      // clock went backwards: keep tokens and the max seen time as reference.
      this._clockBackwards = true;
      // no token change, _lastTime stays at max seen time
    } else {
      // same time: nothing to do
    }
  }

  available() {
    this._advance();
    return this._tokens;
  }

  tryTake(n) {
    if (n === undefined || n === null) n = 1;
    if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }
    this._advance();
    if (this._tokens >= n) {
      this._tokens -= n;
      return true;
    }
    return false;
  }

  msUntil(n) {
    if (n === undefined || n === null) n = 1;
    if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) {
      throw new RangeError('n must be a positive finite number');
    }
    this._advance();

    if (this._tokens >= n) return 0;

    const need = n - this._tokens; // > 0 tokens short
    const ratePerMs = this._ratePerMs;
    if (!(need <= this._capacity)) {
      // cannot ever hold that many
      return Infinity;
    }
    if (ratePerMs <= 0) {
      return Infinity;
    }

    let ms = need / ratePerMs;
    // ceil to a whole number of milliseconds, avoiding float artifacts.
    const result = Math.ceil(ms);
    return Number.isFinite(result) ? result : Infinity;
  }
}

module.exports = { TokenBucket };

